using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PaymentBatchProcessingService.Domain.Entities;
using PaymentBatchProcessingService.Domain.Helpers;

namespace PaymentBatchProcessingService.Infrastructure.DB.Configurations;

public sealed class PaymentAttemptConfiguration : IEntityTypeConfiguration<PaymentAttempt>
{
    public void Configure(EntityTypeBuilder<PaymentAttempt> builder)
    {
        //SQL table name
        builder.ToTable("PaymentAttempts");

        //Primary key configuration, GUID is generated by the application, not the database
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedNever();

        //Foreign key configuration, PaymentId is required
        builder.Property(x => x.PaymentId).IsRequired();

        //Outcome is required, has a maximum length defined, and is stored as a string in the database
        builder.Property(x => x.Outcome).HasConversion<string>().HasMaxLength(Constants.MaxStatusLength).IsUnicode(false).IsRequired();

        //BankReference and FailureReason have maximum lengths defined, can be null
        builder.Property(x => x.BankReference).HasMaxLength(Constants.MaxBankReferenceLength);
        builder.Property(x => x.FailureReason).HasMaxLength(Constants.MaxReasonLength);

        //CreatedAtUtc is not null and is stored as UTC in the database
        builder.Property(x => x.CreatedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => DateTime.SpecifyKind(value, DateTimeKind.Utc)).IsRequired();

        //CompletedAtUtc can be null and is stored as UTC in the database
        builder.Property(x => x.CompletedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => value.HasValue ? DateTime.SpecifyKind(value.Value, DateTimeKind.Utc) : null);

        //PaymentAttempt has one Payment, and Payment has many PaymentAttempts
        //The foreign key is PaymentId, and on delete, the behavior is restricted
        builder.HasOne<Payment>().WithMany().HasForeignKey(x => x.PaymentId).OnDelete(DeleteBehavior.Restrict);
    }
}
